<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class DailyReport extends Model { protected $guarded=[]; protected $casts=["report_date"=>"date","photos"=>"array"]; public function reservation(){return $this->belongsTo(Reservation::class);} public function hotel(){return $this->belongsTo(Hotel::class);} public function pet(){return $this->belongsTo(Pet::class);} public function staff(){return $this->belongsTo(User::class,"staff_id");} }